import java.util.*;class R {int N=71;String s(boolean P,String[]I){var B=new Stack<Integer>();for(var s:I){var a=s.split(",");B.add(new Integer(a[0])+N*new Integer(a[1]));}if(P)return""+f(B,1024);int lo=0,hi=B.size()-1;while(lo<hi){int mid=(lo+hi)/2;if(f(B,mid)<0)hi=mid;else lo=mid+1;}int p=B.get(lo-1);return p%N+","+p/N;}int f(List<Integer>B,int L){boolean[]b=new boolean[N*N],s=b.clone();for(int i=0;i<L;i++)b[B.get(i)]=true;int[]q=new int[N*N],v={-N,N,-1,1};int h=0,t=1;s[0]=true;for(int S=0;h<t;S++)for(int E=t;h<E;){int p=q[h++],c=p%N;if(p==N*N-1)return S;for(int d:v){int n=p+d;if(n>=0&&n<N*N&&Math.abs(n%N-c)<2&!b[n]&!s[n])s[q[t++]=n]=true;}}return-1;}}
